import Snackbar, { SnackbarSubscription } from './model/Snackbar';
interface SnackbarService {
    notify(snackbar: Snackbar): void;
    subscribe(callback: (snackbar: SnackbarSubscription) => void): any;
    unsubscribe(callback: (snackbar: SnackbarSubscription) => void): void;
}
export default SnackbarService;
